import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Tooltip from 'flarum/common/components/Tooltip';
import humanTime from 'flarum/common/utils/humanTime';
/** That a message was edited, and by whom and when on hover, as for posts. */
export default class MessageEdited extends Component {
  view() {
    const message = this.attrs.message;
    const info = app.translator.trans('flarum-messages.forum.message.edited_tooltip', {
      user: message.editedUser() || null,
      ago: humanTime(message.editedAt())
    });
    return m(Tooltip, {
      text: info
    }, m("span", {
      className: "PostEdited"
    }, app.translator.trans('flarum-messages.forum.message.edited_text')));
  }
}
flarum.reg.add('flarum-messages', 'forum/components/MessageEdited', MessageEdited);